rep(38,3,'Vendor-wise Purchase Summary','Purchases by vendor',x=>({cols:[T('k','Vendor'),N('grn','GRNs'),N('u','Units'),M('val','Purchase value'),M('fr','Freight'),M('avg','Avg cost / unit',{nosum:true})],rows:G(GR(x),g=>V.m.vendor[g.vendor].name,{grn:a=>a.length,u:a=>S(a,g=>S(g.lines,l=>l.acc)),val:a=>S(a,g=>g.value),fr:a=>S(a,g=>g.freight),avg:a=>S(a,g=>g.value)/(S(a,g=>S(g.lines,l=>l.acc))||1)}).sort((a,b)=>b.val-a.val)}),{ch:'hbar',y:'val'});
