rep(43,3,'Vendor Performance Scorecard','On-time delivery, quality and returns',x=>({cols:[T('k','Vendor'),Pc('ot','On-time %'),Pc('rej','QC reject %'),N('ret','Returns to vendor'),T('rt','Rating',{nosum:true}),Pc('score','Score')],rows:V.db.vendors.filter(v=>v.weave).map(v=>{const g=V.db.grns.filter(y=>y.vendor===v.id&&y.po),late=g.filter(y=>V.m.po[y.po]&&y.date>V.m.po[y.po].expected).length,ot=g.length?100-late/g.length*100:100,rj=V.pct(S(g,y=>S(y.lines,l=>l.rej)),S(g,y=>S(y.lines,l=>l.recv))),ret=V.db.purchaseReturns.filter(r=>r.vendor===v.id).length;return {k:v.name,ot,rej:rj,ret,rt:'★ '+v.rating,score:Math.max(0,Math.min(100,ot*.5+(100-rj*5)*.35+v.rating*3-ret*3))}}).sort((a,b)=>b.score-a.score)}),{y:'score',asOf:true});
