rep(47,3,'Rate History & Price Variance','Standard vs actual landed cost per design',x=>({cols:[T('k','Design'),M('std','Std cost'),M('avg','Avg actual',{nosum:true}),M('min','Min'),M('max','Max'),Pc('var','Variance %')],rows:V.db.items.filter(i=>i.cat==='Saree').map(i=>{const c=V.db.pieces.filter(p=>p.sku===i.sku).map(p=>p.cost);if(!c.length)return null;const a=S(c)/c.length;return {k:i.name,std:i.cost,avg:a,min:Math.min(...c),max:Math.max(...c),var:(a-i.cost)/i.cost*100}}).filter(Boolean).sort((a,b)=>Math.abs(b.var)-Math.abs(a.var))}),{ch:'hbar',y:'var',limit:12,asOf:true});

