rep(52,4,'Stock Ledger — Movement Report','Every stock movement in the period',x=>({cols:[D('date','Date'),T('time','Time'),T('type','Movement'),T('no','Serial'),T('from','From'),T('to','To'),T('ref','Reference'),T('by','By')],rows:V.db.moves.filter(m=>x.ok(m.date)).map(m=>({date:m.date,time:m.time,type:(V.MV[m.type]||[m.type])[0],no:m.no,from:V.m.loc[m.from]?V.m.loc[m.from].city:m.from,to:V.m.loc[m.to]?V.m.loc[m.to].city:m.to,ref:m.ref,by:V.L.userName(m.by)})).reverse().slice(0,1500)}),{ch:'none'});
